"""Private native preparation shared by views of one complete feature curve.

A feature curve, not necessarily a whole Street, has one interpolation mode
and its own declared endpoint tangents/profile axes. Prepare both authored
directions once. Consumers take original control ranges from these unchanged
tables. No Python-derived curve coordinates or update handlers are involved.

The cache has an explicit coordinate frame. Its reader can translate stored
point coordinates into another XY frame without moving scalar search knots or
altering derivative vectors. This is not automatic object-transform support:
the network adapter must supply the correct translation. Rotation/scale and
binding the cache to the complete network still require separate integration.
"""
import bpy

from . import curved_path_view_nodes as views

c=views.c
PREFIX='Prochitecture Streets / Shared feature curve '
META=(('_st_fc_direction','INT'),('_st_fc_valid','BOOLEAN'),
      ('_st_fc_weighted','BOOLEAN'),('_st_fc_count','INT'),('_st_fc_schema','INT'))


def _copy_inputs(g,original,*,exclude=()):
    for socket in original.interface.items_tree:
        if socket.item_type!='SOCKET' or socket.in_out!='INPUT' or socket.name in exclude:continue
        g.socket(socket.name,socket.socket_type,default=getattr(socket,'default_value',None))


def prepare():
    """Both exact existing directional tables, packaged as two native chains."""
    name=PREFIX+'directional preparation v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    original=views.prepare(endpoint_tangents=True,interpolation=True,endpoint_frames=True)
    g=c.Graph(name)
    _copy_inputs(g,original,exclude=('Reverse','First Control','Last Control'))
    g.socket('Geometry','NodeSocketGeometry','OUTPUT')
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    count=c._count(g,inp.outputs['Geometry'])
    parts=[]
    for direction in (0,1):
        call=g.node('GeometryNodeGroup','Unchanged '+('forward' if direction==0 else 'reverse')+' feature preparation')
        call.node_tree=original
        for socket in inp.outputs:
            if socket.name in call.inputs:g.bind(socket,call.inputs[socket.name])
        g.bind(direction,call.inputs['Reverse'])
        g.bind(0,call.inputs['First Control']);g.bind(count-1.,call.inputs['Last Control'])
        table=call.outputs['Whole Path']
        for (key,kind),value in zip(META,(direction,call.outputs['Valid'],call.outputs['Weighted'],count,1)):
            table=c._store(g,table,key,value,kind)
        parts.append(table)
    from .curved_junction_nodes import _join
    g.bind(_join(g,*parts),out.inputs['Geometry'])
    g.g['st_feature_curve_cache']=1
    return g.g


def view():
    """Select an original authored control interval without fitting again."""
    name=PREFIX+'coefficient-preserving view v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    g.socket('Cache','NodeSocketGeometry')
    g.socket('Reverse','NodeSocketBool',default=False)
    g.socket('Translation','NodeSocketVector')
    for key in ('First Control','Last Control'):g.socket(key,'NodeSocketInt')
    for key,kind in (('Geometry','NodeSocketGeometry'),('Whole Path','NodeSocketGeometry'),
                     ('Length','NodeSocketFloat'),('Origin','NodeSocketFloat'),
                     ('Valid','NodeSocketBool'),('Weighted','NodeSocketBool')):
        g.socket(key,kind,'OUTPUT')
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    table=c._select(g,inp.outputs['Cache'],g.math('COMPARE',c.named(g,'_st_fc_direction','INT'),inp.outputs['Reverse']))
    count=c._count(g,table)
    good=1.
    for key,kind in META:
        attr=g.node('GeometryNodeInputNamedAttribute');attr.data_type=kind
        attr.inputs['Name'].default_value=key;good*=c.V(g,attr.outputs['Exists'])
    good*=g.math('COMPARE',c.named(g,'_st_fc_schema','INT'),1.)
    good*=c.named(g,'_st_fc_valid','BOOLEAN')
    good*=g.math('COMPARE',c.named(g,'_st_fc_count','INT'),count)
    valid=c._stat(g,table,good)*g.math('GREATER_THAN',count,1.5)
    weighted=c._read(g,table,'_st_fc_weighted',0,'BOOLEAN')
    translation=inp.outputs['Translation']
    # Search geometry stores scalar chord parameters. Only st_cc_p is a point
    # coordinate; tangents, polynomial differences and miter vectors are not.
    # A nonzero Z translation would change the planar path contract.
    tx,ty,tz=g.separate(translation)
    valid*=g.math('LESS_THAN',g.math('ABSOLUTE',tz),1e-7)
    for value in (tx,ty):valid*=g.math('LESS_THAN',g.math('ABSOLUTE',value),3e38)
    px,py,pz=g.separate(c.named(g,'st_cc_p','FLOAT_VECTOR'))
    table=c._store(g,table,'st_cc_p',g.xyz(px+tx,py+ty,pz),'FLOAT_VECTOR')
    # The reader's result retains precisely the original path attribute set.
    # Temporary cache tags cannot change downstream attribute propagation.
    for key,_ in META:
        remove=g.node('GeometryNodeRemoveAttribute');remove.inputs['Name'].default_value=key
        g.bind(table,remove.inputs['Geometry']);table=remove.outputs['Geometry']
    selected=g.node('GeometryNodeGroup','Original range validation and coefficient-preserving selection')
    selected.node_tree=views.view()
    g.bind(table,selected.inputs['Path']);g.bind(valid,selected.inputs['Source Valid'])
    first=c.V(g,inp.outputs['First Control']);last=c.V(g,inp.outputs['Last Control'])
    g.bind(c.choose(g,inp.outputs['Reverse'],count-1.-last,first,'INT'),selected.inputs['First Knot'])
    g.bind(c.choose(g,inp.outputs['Reverse'],count-1.-first,last,'INT'),selected.inputs['Last Knot'])
    for key in ('Geometry','Length','Origin','Valid'):g.bind(selected.outputs[key],out.inputs[key])
    g.bind(table,out.inputs['Whole Path']);g.bind(weighted,out.inputs['Weighted'])
    return g.g
